    productDetails: '{"form":"منظف فقاعات أكسجين","size":"180ml (منزلي) / 500ml (احترافي)","target":"تنظيف عميق وتغذية البشرة","technology":"فقاعات أكسجين تتكوّن عند الاستخدام","keyBenefits":"تنظيف لطيف، فقاعات أكسجين، إزالة المكياج","usage":"تنظيف صباحي ومسائي","skinType":"جميع أنواع البشرة، خاصة البشرة الحساسة","application":"ضع على وجه جاف مع تجنب العينين؛ عند تكوّن الفقاعات دلك بحركات دائرية واشطف بماء فاتر","formulation":"تقنية فقاعات أكسجين مع مواد خافضة للتوتر السطحي لطيفة","origin":"كوريا الجنوبية"}',
    keyFeatures: '[{"title":"يُستخدم على وجه جاف","description":"بخلاف المنظفات الرغوية، يُوضع هذا المنظف على بشرة جافة. تتكوّن الفقاعات عند التلامس، ثم تدليك دائري وشطف بماء فاتر."},{"title":"تنظيف لطيف","description":"إزالة فعالة للمكياج والشوائب بدون حركة تنظيف مفرطة أو تهيج البشرة."},{"title":"فقاعات أكسجين طبيعية","description":"فقاعات أكسجين مولدة طبيعياً توفر إحساس علاج فاخر أثناء تنظيف البشرة."},{"title":"صيغة شاملة","description":"منظف شامل يزيل المكياج والأوساخ والشوائب مع تغذية البشرة."}]',
