    keyFeatures: '[{"title":"مجمع الأحماض الأمينية NMF","description":"مزيج مطابق للبشرة من 17 حمضاً أمينياً يحاكي عامل الترطيب الطبيعي للاحتفاظ الأمثل بالماء."},{"title":"سيراميد NP","description":"دهون مطابقة للبشرة تدعم سلامة الحاجز وتوازن الرطوبة."},{"title":"زبدة الشيا وزيت المكاديميا","description":"مطريات غنية تغذي بعمق وتحمي البشرة من الإجهاد البيئي."},{"title":"الاحتفاظ بالماء","description":"يعزز الاحتفاظ الأمثل بالماء لبشرة صحية ورطبة وناعمة."}]',
    benefits: '["حماية الحاجز - يقوي ويحمي حاجز البشرة من الأضرار البيئية","الاحتفاظ بالرطوبة - يعزز الاحتفاظ الأمثل بالماء لبشرة صحية ورطبة","تنعيم البشرة - يساعد على تحقيق ملمس بشرة ناعم وسلس ومرن","إصلاح الحاجز - يساعد على إصلاح واستعادة وظيفة حاجز البشرة المعرضة","الترطيب طويل الأمد - يوفر رطوبة مستمرة للراحة طوال اليوم","صيغة لطيفة - مناسبة للبشرة الحساسة والمعرضة"]',
    ingredients: '[{"name":"مجمع الأحماض الأمينية NMF","description":"مزيج من 17 حمضاً أمينياً مطابقاً للبشرة (جليسين، سيرين، حمض الجلوتاميك، ليوسين، لايسين، أرجينين وغيرها) يدعم سلامة الحاجز وعمليات الإصلاح الطبيعية."},{"name":"سيراميد NP","description":"سيراميد مطابق للبشرة يساعد على الحفاظ على وظيفة وسلامة حاجز البشرة."},{"name":"زبدة الشيا","description":"مطري غني يوفر ترطيباً عميقاً ويساعد على حماية البشرة من الإجهاد البيئي."},{"name":"زيت المكاديميا","description":"زيت مغذي يساعد على استعادة وظيفة حاجز البشرة ويوفر حماية مضادة للأكسدة."},{"name":"الجلسرين + بوليديسين مهدرج","description":"العمود الفقري المطري الذي يمنح الكريم إحساس ترطيب يدوم طويلاً."}]',
    howToUse: '[{"step":"التحضير","instruction":"نظف البشرة جيداً وضع التونر إذا رغبت"},{"step":"التطبيق","instruction":"ضع كمية وفيرة على الوجه والرقبة"},{"step":"التدليك","instruction":"دلك برفق في حركات صاعدة حتى يتم الامتصاص الكامل"},{"step":"التكرار","instruction":"استخدم صباحاً ومساءً للحصول على أفضل النتائج"},{"step":"المناطق المستهدفة","instruction":"ركز على المناطق ذات حاجز البشرة المعرض"},{"step":"النتائج","instruction":"تحسن واضح في وظيفة حاجز البشرة خلال 2-4 أسابيع"}]',
