    keyFeatures: '[{"title":"ترطيب متعدد المستويات","description":"ترطيب متعدد الطبقات المتقدم يبرد ويجذب ويجدد ويحبس الرطوبة لترطيب شامل للبشرة."},{"title":"مركب Hyaluronan 11","description":"مركب حمض الهيالورونيك المتقدم بأوزان جزيئية متعددة للاختراق العميق والحماية السطحية."},{"title":"سكاريد أيزوميرات","description":"مغناطيس رطوبة مطابق للبشرة يرتبط بالبشرة لترطيب مستدام."},{"title":"مركب مستخلصات الفطر","description":"خصائص قوية مضادة للالتهابات ومضادة للأكسدة من مستخلصات الفطر المختلفة لتغذية وحماية البشرة."}]',
    benefits: '["الترطيب العميق - توصيل رطوبة متعدد الطبقات لترطيب شامل للبشرة","نتائج طويلة الأمد - ترطيب متعدد المستويات يدوم طويلاً","حماية حاجز البشرة - يقوي حاجز الرطوبة لمنع فقدان الماء","إحساس التبريد - عوامل التبريد الطبيعية توفر إنعاش فوري للبشرة","فوائد مكافحة الشيخوخة - يقلل الخطوط الدقيقة ويحسن مرونة البشرة","جميع أنواع البشرة - مناسب لجميع أنواع البشرة، بما في ذلك الحساسة","نتائج احترافية - ترطيب بجودة الصالون في المنزل"]',
