    howToUse: '[{"step":"التنظيف","instruction":"ابدأ ببشرة نظيفة وجافة"},{"step":"التطبيق","instruction":"خذي كمية صغيرة ودلكي برفق على الوجه والرقبة"},{"step":"التدليك","instruction":"استخدمي حركات دائرية صاعدة حتى يتم الامتصاص الكامل"},{"step":"التكرار","instruction":"استخدمي صباحاً ومساءً للحصول على أفضل النتائج"},{"step":"المتابعة","instruction":"طبقيه واقي الشمس أثناء النهار"}]',
