    productDetails: '{"form":"قناع هيدروجيل حراري حساس احترافي","size":"38غ x 5ea","target":"العناية بعد العلاج وعلاج التبريد","technology":"تقنية هيدروجيل حراري حساس مبتكرة","keyBenefits":"راحة تبريد فورية، ترطيب عميق، اختراق محسن","usage":"علاجات احترافية، رعاية ما بعد الإجراء","skinType":"جميع أنواع البشرة، خاصة البشرة بعد العلاج","application":"ضع بالتساوي على منطقة العلاج، تجنب منطقة العين","duration":"15-20 دقيقة للحصول على أفضل النتائج","origin":"كوريا الجنوبية"}',
    keyFeatures: '[{"title":"تقنية الحساسية الحرارية","description":"هيدروجيل مبتكر يتحول من هلام إلى سائل عند درجة حرارة الجسم لالتصاق البشرة المحسن واختراق المكونات."},{"title":"تأثير التبريد الفوري","description":"يوفر راحة تبريد فورية عن طريق إزاحة حرارة البشرة بالرطوبة، مثالي للعناية بعد العلاج."},{"title":"صيغة الببتيد المتقدمة","description":"يحتوي على Acetyl Hexapeptide-8 وببتيدات أخرى لتجديد البشرة والشفاء المحسن."},{"title":"العناية بعد العلاج","description":"موصى به خصيصاً بعد الإجراءات الجلدية مثل علاجات الليزر والميكرونيدلينج."}]',
    benefits: '["راحة تبريد فورية - يوفر إحساس تبريد فوري لتهدئة البشرة المتهيجة","ترطيب عميق - يوفر رطوبة مكثفة للتعافي الأمثل للبشرة","اختراق محسن - تقنية الحساسية الحرارية تضمن أقصى امتصاص للمكونات","شفاء ما بعد العلاج - يعجل التعافي بعد الإجراءات الجلدية","راحة البشرة - يقلل الالتهاب والتهيج من العلاجات","نتائج احترافية - صيغة احترافية للعلاجات المتقدمة للعناية بالبشرة"]',
    ingredients: '[{"name":"Acetyl Hexapeptide-8","description":"ببتيد متقدم يساعد في استرخاء عضلات الوجه وتقليل خطوط التعبير للبشرة أكثر سلاسة."},{"name":"حمض الهيالورونيك","description":"مادة مرطبة قوية تجذب وتحتفظ بالرطوبة للترطيب العميق وتأثيرات الانتفاخ."},{"name":"الكولاجين المتحلل مائياً","description":"ببتيدات الكولاجين النشطة بيولوجياً التي تدعم بنية البشرة وتعزز المرونة."},{"name":"مستخلص Chondrus Crispus","description":"مستخلص الكاراجينان الطبيعي الذي يوفر فوائد مهدئة ومضادة للالتهابات."},{"name":"Dipotassium Glycyrrhizate","description":"مشتق جذر عرق السوس الذي يوفر خصائص مضادة للالتهابات ومهدئة."}]',
    howToUse: '[{"step":"التنظيف","instruction":"نظف وجهك جيداً وربت حتى يجف"},{"step":"التطبيق","instruction":"ضع قناع الهيدروجيل بالتساوي على الوجه، مع تجنب منطقة العين"},{"step":"الاسترخاء","instruction":"اتركه لمدة 15-20 دقيقة أثناء الاسترخاء"},{"step":"الإزالة","instruction":"أزل القناع برفق من الحواف"},{"step":"الربت","instruction":"ربت برفق أي بقايا في البشرة"},{"step":"التكرار","instruction":"استخدم بعد العلاجات الاحترافية للتعافي الأمثل"}]',
