    keyFeatures: '[{"title":"حماية فائقة","description":"SPF 50+ PA++++ يوفر حماية قصوى ضد أشعة UVA و UVB."},{"title":"صيغة غير دهنية","description":"ملمس حريري خفيف الوزن يمتص بسرعة بدون ترك بقايا دهنية."},{"title":"مجمع رعاية حروق الشمس","description":"مجمع متخصص يساعد في تعزيز تعافي البشرة من أضرار الشمس والتعرض."},{"title":"صيغة آمنة للشعاب المرجانية","description":"صيغة صديقة للبيئة آمنة للشعاب المرجانية والحياة البحرية."}]',
